BEGIN;
CREATE TABLE chores.task_templates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200),description text NOT NULL DEFAULT '',assignee_id uuid,repeat_days integer CHECK(repeat_days BETWEEN 1 AND 366),timezone text NOT NULL DEFAULT 'Europe/Vienna',active boolean NOT NULL DEFAULT true,created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),FOREIGN KEY(household_id,assignee_id) REFERENCES core.memberships(household_id,id));
CREATE TABLE chores.task_occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),household_id uuid NOT NULL REFERENCES core.households(id),template_id uuid NOT NULL,occurrence_key text NOT NULL,due_at timestamptz NOT NULL,assignee_id uuid,state text NOT NULL DEFAULT 'open' CHECK(state IN('open','completed','skipped')),completed_at timestamptz,completed_by uuid REFERENCES core.users(id),created_by uuid NOT NULL REFERENCES core.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 1,UNIQUE(household_id,id),UNIQUE(template_id,occurrence_key),FOREIGN KEY(household_id,template_id) REFERENCES chores.task_templates(household_id,id),FOREIGN KEY(household_id,assignee_id) REFERENCES core.memberships(household_id,id),CHECK((state='completed')=(completed_at IS NOT NULL)));
CREATE INDEX chores_due ON chores.task_occurrences(household_id,state,due_at);
GRANT USAGE ON SCHEMA chores TO household_app; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA chores TO household_app;
COMMIT;
